		for (int ordinal = 0; ordinal < query.scalarChildCount(scalarId); ordinal++) {
			scalarCost(query, memo, query.scalarChild(scalarId, ordinal), inputContextId, outerBindingMaskId,
					expectedInvocations, destination);
		}
